<?php if (!$user): ?><h1 class="h4 mb-3">Pour obtenir plus d’informations sur un trajet, veuillez vous connecter</h1><?php else: ?><h1 class="h4 mb-3">Trajets proposés</h1><?php endif; ?>
<div class="table-responsive"><table class="table table-striped align-middle"><thead class="table-dark"><tr><th>Départ</th><th>Date</th><th>Heure</th><th>Destination</th><th>Date</th><th>Heure</th><th>Places</th><?php if ($user): ?><th>Actions</th><?php endif; ?></tr></thead><tbody>
<?php foreach ($trips as $trip): ?><tr><td><?= e($trip['departure_name']) ?></td><td><?= e(date('d/m/Y', strtotime($trip['departure_at']))) ?></td><td><?= e(date('H:i', strtotime($trip['departure_at']))) ?></td><td><?= e($trip['arrival_name']) ?></td><td><?= e(date('d/m/Y', strtotime($trip['arrival_at']))) ?></td><td><?= e(date('H:i', strtotime($trip['arrival_at']))) ?></td><td><?= e($trip['available_seats']) ?></td>
<?php if ($user): ?><td class="text-nowrap"><button class="btn btn-sm btn-outline-dark" data-bs-toggle="modal" data-bs-target="#trip<?= (int) $trip['id'] ?>">Détails</button> <?php if ($user['role'] === 'admin' || (int) $user['id'] === (int) $trip['author_id']): ?><a class="btn btn-sm btn-outline-secondary" href="/trips/<?= (int) $trip['id'] ?>/edit">Modifier</a> <form method="post" action="/trips/<?= (int) $trip['id'] ?>/delete" class="d-inline" onsubmit="return confirm('Supprimer ce trajet ?')"><?= token() ?><button class="btn btn-sm btn-outline-danger">Supprimer</button></form><?php endif; ?></td><?php endif; ?></tr>

<?php endforeach; ?></tbody></table></div><?php if ($user): foreach ($trips as $trip): ?><div class="modal fade" id="trip<?= (int) $trip['id'] ?>" tabindex="-1" aria-labelledby="title<?= (int) $trip['id'] ?>"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5" id="title<?= (int) $trip['id'] ?>">Détails du trajet</h2><button class="btn-close" data-bs-dismiss="modal" aria-label="Fermer"></button></div><div class="modal-body"><p>Auteur : <?= e($trip['first_name'] . ' ' . $trip['last_name']) ?></p><p>Téléphone : <?= e($trip['phone']) ?></p><p>Email : <a href="mailto:<?= e($trip['email']) ?>"><?= e($trip['email']) ?></a></p><p>Nombre total de places : <?= e($trip['total_seats']) ?></p></div><div class="modal-footer"><button class="btn btn-secondary" data-bs-dismiss="modal">Fermer</button></div></div></div></div><?php endforeach; endif; ?><?php if (!$trips): ?><p>Aucun trajet disponible pour le moment.</p><?php endif; ?>
